//! The rules a motorway is generated by, once its roads are on the map: which of
//! its stretches go on a bridge, through a tunnel or along the ground; where a road
//! crossing another needs a bridge to do it; and how the land is cut and filled to
//! meet what stays on the ground.
//!
//! Every rule reads the **natural** land: the country's height from the roads
//! that are not the corridor's, the parts' rims and toes, and the hills, before
//! anything is cut or filled for the motorway. A motorway is fitted to the land,
//! not the other way round, so its own heights are left out of it.

use roadgen_core::geometry::plan::{ring_contains, PlanPoint, Segments};
use roadgen_core::geometry::Point3;
use roadgen_core::id::RoadId;
use roadgen_core::map::Map;
use roadgen_core::structure::{
    self, BridgeForm, BridgeSpec, RoadSpan, StructureSpec, TunnelForm, TunnelSpec,
};

use super::corridor::StructureMode;
use super::land::{at_grade_edges, plan_of, Line, Rise};
use crate::ground::Field;

/// Above the land by more than this, a corridor's road goes on a bridge, metres;
/// and the bridge reaches out to where it is this far above.
const BRIDGE: f64 = 8.0;
const ABUTMENT: f64 = 5.0;
/// Below the land by more than a tunnel's height and this much cover, it goes in a
/// tunnel; and the tunnel reaches out to where the cover is this thin, metres.
const COVER: f64 = 10.0;
const PORTAL: f64 = 2.0;
/// The shortest structure the rules make, and the shortest stretch of ground they
/// leave between two, metres.
const SHORTEST: f64 = 30.0;
const GAP: f64 = 50.0;
/// How far apart a road is read, metres.
const STEP: f64 = 5.0;
use roadgen_core::structure::{CLEARANCE, OVERPASS_DECK};
/// A fill's and a cut's slope: metres out for every metre down or up.
const FILL: f64 = 1.8;
const CUT: f64 = 1.2;
/// The furthest out a slope is run before it is given up on, metres.
const FURTHEST: f64 = 80.0;

/// The natural land, before the motorway.
pub(crate) struct Natural<'a> {
    pub field: Option<Field>,
    pub rises: &'a [Rise],
}

impl Natural<'_> {
    pub fn height(&self, x: f64, y: f64) -> f64 {
        self.field.as_ref().map_or(0.0, |field| field.height(x, y))
            + self.rises.iter().map(|rise| rise.at([x, y])).sum::<f64>()
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Class {
    Ground,
    Bridge,
    Tunnel,
    /// Already on a structure the caller put there.
    Fixed,
}

/// Chooses the structures of every corridor road whose corridor leaves them to the
/// land. Returns the notes worth telling the caller.
pub(crate) fn choose_structures(
    map: &mut Map,
    roads: &[(RoadId, String)],
    modes: &[(String, StructureMode)],
    natural: &Natural,
    water: &[Vec<PlanPoint>],
) -> Vec<String> {
    let mut notes = Vec::new();
    let tunnel = TunnelSpec::default();
    let deep = tunnel.clear_height + tunnel.lining;
    for (id, corridor) in roads {
        let auto = modes
            .iter()
            .find(|(name, _)| name == corridor)
            .is_none_or(|(_, mode)| *mode == StructureMode::Auto);
        if !auto {
            continue;
        }
        let Some(road) = map.road(id) else { continue };
        if road.is_connector() {
            continue;
        }
        // The road at each of its own vertices, sampled once: classified, and
        // whether it is over water.
        let Ok(samples) = road.reference_line.samples(map.metadata.sampling) else {
            continue;
        };
        let mut rows: Vec<(f64, f64, Class)> = Vec::with_capacity(samples.len());
        let mut wet: Vec<f64> = Vec::new();
        for sample in samples {
            let (station, p) = (sample.station, sample.point);
            let d = p.z - natural.height(p.x, p.y);
            let over_water = water.iter().any(|ring| ring_contains(ring, [p.x, p.y]));
            if over_water {
                wet.push(station);
            }
            let class = if road.structure.at(station).is_some() {
                Class::Fixed
            } else if over_water || d > BRIDGE {
                Class::Bridge
            } else if d < -(deep + COVER) {
                Class::Tunnel
            } else {
                Class::Ground
            };
            rows.push((station, d, class));
        }
        let over_water = |from: f64, to: f64| wet.iter().any(|s| *s >= from && *s <= to);
        for (kind, extend) in [(Class::Bridge, ABUTMENT), (Class::Tunnel, deep + PORTAL)] {
            let runs = runs_of(&rows, kind, extend);
            for (from, to) in runs {
                let spans = [RoadSpan::new(id.clone(), from, to)];
                let spec = match kind {
                    Class::Bridge => StructureSpec::Bridge(BridgeSpec {
                        form: if to - from >= 100.0 && !over_water(from, to) {
                            BridgeForm::Viaduct
                        } else {
                            BridgeForm::Bridge
                        },
                        ..BridgeSpec::default()
                    }),
                    _ => StructureSpec::Tunnel(TunnelSpec {
                        form: TunnelForm::Bored,
                        ..TunnelSpec::default()
                    }),
                };
                if let Err(error) = structure::place(map, &spans, &spec) {
                    notes.push(format!("{id} {from:.0}–{to:.0} m: no structure: {error}"));
                }
            }
        }
    }
    notes
}

/// The stretches of `rows` of class `kind`: each long enough, those close together
/// joined, and each reached out to where it is no more than `extend` off the land.
fn runs_of(rows: &[(f64, f64, Class)], kind: Class, extend: f64) -> Vec<(f64, f64)> {
    let mut runs: Vec<(usize, usize)> = Vec::new();
    let mut start: Option<usize> = None;
    for (index, row) in rows.iter().enumerate() {
        if row.2 == kind {
            start.get_or_insert(index);
        } else if let Some(from) = start.take() {
            runs.push((from, index - 1));
        }
    }
    if let Some(from) = start {
        runs.push((from, rows.len() - 1));
    }
    // Joined across a short stretch of ground, but never across a structure the
    // caller put there.
    let mut joined: Vec<(usize, usize)> = Vec::new();
    for run in runs {
        if let Some(last) = joined.last_mut() {
            let gap = rows[run.0].0 - rows[last.1].0;
            let clear = rows[last.1..=run.0].iter().all(|row| row.2 != Class::Fixed);
            if gap < GAP && clear {
                last.1 = run.1;
                continue;
            }
        }
        joined.push(run);
    }
    let off = |row: &(f64, f64, Class)| match kind {
        Class::Bridge => row.1 > extend,
        _ => row.1 < -extend,
    };
    joined
        .into_iter()
        .map(|(mut from, mut to)| {
            while from > 0 && rows[from - 1].2 != Class::Fixed && off(&rows[from - 1]) {
                from -= 1;
            }
            while to + 1 < rows.len() && rows[to + 1].2 != Class::Fixed && off(&rows[to + 1]) {
                to += 1;
            }
            (rows[from].0, rows[to].0)
        })
        .filter(|(from, to)| to - from >= SHORTEST)
        .collect()
}

/// Where a road crosses over another with nothing under it, puts an overpass under
/// it; then derives every grade separation. A crossing too close to carry is left
/// for validation to report, and noted.
pub(crate) fn separate(map: &mut Map) -> Vec<String> {
    let mut notes = Vec::new();
    for crossing in structure::crossings(map) {
        if crossing.carried_by(map).is_some() {
            continue;
        }
        let strict = crossing.strict(map);
        let ((upper, us, uz), (lower, ls, lz)) = crossing.ordered();
        let (upper, lower) = (upper.clone(), lower.clone());
        let gap = uz - lz;
        if gap < OVERPASS_DECK + 0.5 {
            if strict {
                notes.push(format!(
                    "{upper} at {us:.0} m and {lower} at {ls:.0} m cross {gap:.1} m apart: too \
                     close for a bridge; lift one of them"
                ));
            }
            continue;
        }
        if gap < CLEARANCE + OVERPASS_DECK {
            notes.push(format!(
                "{upper} at {us:.0} m clears {lower} by {:.1} m, under the {CLEARANCE} m a \
                 vehicle needs",
                gap - OVERPASS_DECK
            ));
        }
        let reach = abutment_reach(gap - OVERPASS_DECK);
        let mut span = structure::span_across(map, &upper, us, &lower, ls);
        span.from = (span.from - reach).max(0.0);
        let length = map
            .road(&upper)
            .and_then(|road| road.horizontal_length().ok())
            .unwrap_or(span.to);
        span.to = (span.to + reach).min(length);
        let spec = StructureSpec::Bridge(BridgeSpec::for_form(BridgeForm::Overpass));
        if let Err(error) = structure::place(map, &[span], &spec) {
            notes.push(format!("{upper} over {lower}: no overpass: {error}"));
        }
    }
    notes
}

/// How far past what it crosses a bridge reaches, for the land to come down from
/// its abutments to the road below at a fill's slope: `height` over it.
pub(crate) fn abutment_reach(height: f64) -> f64 {
    2.0 + height.max(0.0) * FILL
}

/// How far a road may stand off the natural land and still have a frontage,
/// metres.
const FRONTAGE: f64 = 1.5;

/// The stretches of `roads` that stand more than [`FRONTAGE`] off the natural land
/// — an embankment, a cutting — each as an outline reaching a lot's depth past the
/// road, for buildings to keep out of.
pub(crate) fn off_the_land(map: &Map, roads: &[RoadId], natural: &Natural) -> Vec<Vec<PlanPoint>> {
    let mut rings = Vec::new();
    for id in roads {
        let Some(road) = map.road(id) else { continue };
        let Ok(length) = road.horizontal_length() else {
            continue;
        };
        let count = (length / STEP).ceil().max(1.0) as usize;
        let mut run: Option<f64> = None;
        let close = |from: f64, to: f64, rings: &mut Vec<Vec<PlanPoint>>| {
            let span = RoadSpan::new(id.clone(), (from - 10.0).max(0.0), (to + 10.0).min(length));
            if span.length() > 1.0 {
                if let Ok(ring) = structure::outline(map, &[span], 25.0) {
                    rings.push(plan_of(&ring));
                }
            }
        };
        for index in 0..=count {
            let station = length * index as f64 / count as f64;
            let Ok(sample) = road
                .reference_line
                .sample_at(station, map.metadata.sampling)
            else {
                continue;
            };
            let p = sample.point;
            let off = (p.z - natural.height(p.x, p.y)).abs() > FRONTAGE;
            match (off, run) {
                (true, None) => run = Some(station),
                (false, Some(from)) => {
                    close(from, station, &mut rings);
                    run = None;
                }
                _ => {}
            }
        }
        if let Some(from) = run {
            close(from, length, &mut rings);
        }
    }
    rings
}

/// The land's cut and fill along a corridor's roads where they are on the ground:
/// from each edge a slope runs out at [`FILL`] down to the natural land, or at
/// [`CUT`] up to it. Each slope's far edge is a breakline; what lies between it
/// and the road is shaped by the two, and is a land cover — an embankment or a
/// cutting.
pub(crate) struct Earthworks {
    pub lines: Vec<Line>,
    pub holes: Vec<Vec<PlanPoint>>,
    /// `(kind, outline)`, at the land's height.
    pub covers: Vec<(String, Vec<Point3>)>,
    /// The road each of `covers` is the slope of.
    pub owners: Vec<RoadId>,
}

pub(crate) fn earthworks(map: &Map, roads: &[RoadId], natural: &Natural) -> Earthworks {
    let mut out = Earthworks {
        lines: Vec::new(),
        holes: Vec::new(),
        covers: Vec::new(),
        owners: Vec::new(),
    };
    // Every road's outline, to stop a slope where it runs into another road.
    let mut edges = Segments::new(20.0);
    for road in map.roads.iter() {
        for (left, right) in at_grade_edges(map, road) {
            edges.insert_polyline(&plan_of(&left));
            edges.insert_polyline(&plan_of(&right));
        }
    }
    for id in roads {
        let Some(road) = map.road(id) else { continue };
        if road.is_connector() {
            continue;
        }
        for (run, (left, right)) in at_grade_edges(map, road).into_iter().enumerate() {
            for (side, points, sign) in [("left", left, 1.0), ("right", right, -1.0)] {
                slopes(
                    &format!("{}/{run}/{side}", id.local_name()),
                    &points,
                    sign,
                    natural,
                    &edges,
                    &mut out,
                );
            }
        }
        out.owners.resize(out.covers.len(), id.clone());
    }
    out
}

/// The slope out from one edge: `sign` +1 for a left edge, whose outside is to
/// the left of the way the points run.
fn slopes(
    key: &str,
    points: &[Point3],
    sign: f64,
    natural: &Natural,
    edges: &Segments,
    out: &mut Earthworks,
) {
    if points.len() < 2 {
        return;
    }
    // Each edge point's far edge, or none where the land already meets the road.
    let mut feet: Vec<Option<(Point3, bool)>> = Vec::with_capacity(points.len());
    for index in 0..points.len() {
        let a = points[index.saturating_sub(1)];
        let b = points[(index + 1).min(points.len() - 1)];
        let (dx, dy) = (b.x - a.x, b.y - a.y);
        let len = dx.hypot(dy).max(1e-9);
        let (nx, ny) = (-dy / len * sign, dx / len * sign);
        let p = points[index];
        let difference = p.z - natural.height(p.x, p.y);
        if difference.abs() < 0.3 {
            feet.push(None);
            continue;
        }
        let fill = difference > 0.0;
        let mut found = None;
        let mut x = 0.5;
        while x <= FURTHEST {
            let (qx, qy) = (p.x + nx * x, p.y + ny * x);
            // Into another road: the slope stops, and the land is left to it.
            if x > 1.0 && edges.within([qx, qy], 0.5).is_some() {
                break;
            }
            let land = natural.height(qx, qy);
            let slope = if fill { p.z - x / FILL } else { p.z + x / CUT };
            if (fill && slope <= land) || (!fill && slope >= land) {
                found = Some((Point3::new(qx, qy, land), fill));
                break;
            }
            x += 0.5;
        }
        feet.push(found.filter(|(foot, _)| foot.horizontal_distance_to(p) > 0.75));
    }
    // Runs of the same kind of slope, each its own line.
    let mut start = 0;
    let mut count = 0;
    while start < points.len() {
        let Some((_, fill)) = feet[start] else {
            start += 1;
            continue;
        };
        let mut end = start;
        while end + 1 < points.len() && feet[end + 1].is_some_and(|(_, f)| f == fill) {
            end += 1;
        }
        if end > start {
            let edge: Vec<Point3> = points[start..=end].to_vec();
            let foot: Vec<Point3> = feet[start..=end]
                .iter()
                .map(|f| f.expect("in a run").0)
                .collect();
            let kind = if fill { "fill_toe" } else { "cut_crest" };
            out.lines.push(Line {
                key: format!("{key}/{kind}/{count}"),
                kind,
                points: foot.clone(),
                closed: false,
            });
            let ring: Vec<Point3> = edge.iter().copied().chain(foot.into_iter().rev()).collect();
            out.holes.push(plan_of(&ring));
            out.covers
                .push((if fill { "embankment" } else { "cutting" }.to_owned(), ring));
            count += 1;
        }
        start = end + 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_stretch_high_above_the_land_is_a_bridge_reaching_to_its_abutments() {
        // 0–100 m on the ground, 100–200 m 12 m up, then back down.
        let rows: Vec<(f64, f64, Class)> = (0..=60)
            .map(|i| {
                let s = i as f64 * 5.0;
                let d = if (100.0..=200.0).contains(&s) {
                    12.0
                } else if (90.0..100.0).contains(&s) || (200.0..210.0).contains(&s) {
                    6.0
                } else {
                    0.0
                };
                let class = if d > BRIDGE {
                    Class::Bridge
                } else {
                    Class::Ground
                };
                (s, d, class)
            })
            .collect();
        let runs = runs_of(&rows, Class::Bridge, ABUTMENT);
        assert_eq!(runs, vec![(90.0, 205.0)]);
    }

    #[test]
    fn two_bridges_close_together_are_one() {
        let rows: Vec<(f64, f64, Class)> = (0..=60)
            .map(|i| {
                let s = i as f64 * 5.0;
                let high = (50.0..100.0).contains(&s) || (130.0..180.0).contains(&s);
                (
                    s,
                    if high { 12.0 } else { 0.0 },
                    if high { Class::Bridge } else { Class::Ground },
                )
            })
            .collect();
        assert_eq!(runs_of(&rows, Class::Bridge, ABUTMENT), vec![(50.0, 175.0)]);
    }
}
